import{_ as i,c as a,o as n,b0 as e}from"./chunks/framework.Becqh7-x.js";const l="/linux-dev-docs/assets/image-20240831105732279.BLVvgoyC.png",t="/linux-dev-docs/assets/image-20240831103306372.DfhtCtXH.png",p="/linux-dev-docs/assets/image-20240831113614991.DcrYX9lX.png",h="/linux-dev-docs/assets/image-20240831113547106.Bo3_LFMR.png",m=JSON.parse('{"title":"LV055-挂载ubuntu目录","description":null,"frontmatter":{"title":"LV055-挂载ubuntu目录","date":"2026-01-06T10:13:26.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/platform/imx6ull/126d2c6d624e02e7038c2e81","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-06T10:13:26.046Z","fulluuid":"7038c2e81363410392c304075fd70c82","useduuid":"7038c2e81"}},"headers":[],"relativePath":"sdoc/platform/imx6ull/126d2c6d624e02e7038c2e81.md","filePath":"sdoc/10-开发平台/05-IMX6ULL/LV055-挂载ubuntu目录.md","lastUpdated":1768604092000}'),r={name:"sdoc/platform/imx6ull/126d2c6d624e02e7038c2e81.md"};function d(u,s,k,o,c,F){return n(),a("div",null,[...s[0]||(s[0]=[e('<h1 id="lv055-挂载ubuntu目录" tabindex="-1">LV055-挂载ubuntu目录 <a class="header-anchor" href="#lv055-挂载ubuntu目录" aria-label="Permalink to &quot;LV055-挂载ubuntu目录&quot;">​</a></h1><h2 id="一、写在最前面的" tabindex="-1">一、写在最前面的 <a class="header-anchor" href="#一、写在最前面的" aria-label="Permalink to &quot;一、写在最前面的&quot;">​</a></h2><p>前面我们已经知道了如何从 tftp 加载设备树和 linux 内核镜像，如何从 nfs 挂载根文件系统，我们后面进行应用开发的时候是不需要修改根文件系统和镜像以及设备树这些的，每次都这么加载会很慢，但是其实我们有时候只是想把文件传输到开发板而已，可以怎么做？前面不是已经实现了从 nfs 挂载根文件系统到 linux 开发板吗，是不是可以用一样的操作？当然可以的。</p><p>这一节我们从 SD 卡或者 eMMC 启动系统，然后从 nfs 挂载 ubuntu 中的目录到开发板中去。</p><h2 id="二、ubuntu-搭建好-nfs-环境" tabindex="-1">二、ubuntu 搭建好 NFS 环境 <a class="header-anchor" href="#二、ubuntu-搭建好-nfs-环境" aria-label="Permalink to &quot;二、ubuntu 搭建好 NFS 环境&quot;">​</a></h2><h3 id="_1-搭建-nfs-环境" tabindex="-1">1. 搭建 NFS 环境 <a class="header-anchor" href="#_1-搭建-nfs-环境" aria-label="Permalink to &quot;1. 搭建 NFS 环境&quot;">​</a></h3><p>根据《<a href="/linux-dev-docs/sdoc/dev-env/env-net/126b1ad8e7b808bc1b6344ed.html">05-开发环境/15-网络环境/LV025-nfs 环境.md</a>》搭建好 NFS 服务器：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">showmount</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><img src="'+l+'" alt="image-20240831105732279" style="zoom:67%;"><h3 id="_2-创建-app-目录" tabindex="-1">2. 创建 app 目录 <a class="header-anchor" href="#_2-创建-app-目录" aria-label="Permalink to &quot;2. 创建 app 目录&quot;">​</a></h3><p>我们创建一个目录，用与后面应用开发使用：</p><img src="'+t+`" alt="image-20240831103306372" style="zoom:67%;"><h2 id="三、网口实现挂载" tabindex="-1">三、网口实现挂载 <a class="header-anchor" href="#三、网口实现挂载" aria-label="Permalink to &quot;三、网口实现挂载&quot;">​</a></h2><h3 id="_1-环境准备" tabindex="-1">1. 环境准备 <a class="header-anchor" href="#_1-环境准备" aria-label="Permalink to &quot;1. 环境准备&quot;">​</a></h3><p>这个方式需要连接网线，我们需要提前配置好 ubuntu、windows 和 linux 开发板的 IP：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">开发板</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> IP:192.168.10.109</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">虚拟机</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> IP:192.168.10.108</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PC</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    IP:192.168.10.100</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>保证他们可以互相 ping 通即可，其实 PC 的在这里并不重要，主要是要保证虚拟机的 Ubuntu 可以和开发板互相 ping 通。</p><h3 id="_2-linux-开发板挂载目录" tabindex="-1">2. linux 开发板挂载目录 <a class="header-anchor" href="#_2-linux-开发板挂载目录" aria-label="Permalink to &quot;2. linux 开发板挂载目录&quot;">​</a></h3><p>我们在 <code>/mnt</code> 目录下创建挂载点，注意这个目录下创建的文件，好像关机后并不会消失，不需要重新创建：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mnt/nfs_app</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>挂载命令如下：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mount</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nfs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nolock,nfsvers=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 192.168.10.108:/home/sumu/4nfs/app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mnt/nfs_app</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>然后就可以成功挂载啦。</p><h3 id="_3-开机自动挂载" tabindex="-1">3. 开机自动挂载 <a class="header-anchor" href="#_3-开机自动挂载" aria-label="Permalink to &quot;3. 开机自动挂载&quot;">​</a></h3><p>如何实现开机自动挂载？我们需要把这些挂载的命令写到 <code>/etc/init.d/rcS</code> 中去</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mount</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nfs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nolock,nfsvers=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 192.168.10.108:/home/sumu/4nfs/app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mn/nfs_app</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>不过这里会有一个问题，直接写到这个文件中的话，这个时候开发板的 IP 还没设置好，前面我们设置静态 IP 的时候，是修改的 <code>/etc/rc.local</code> 这个文件，这个文件也会在开机的时候自动执行，所以我们把命令写入到 IP 配置之后。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/rc.local</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>然后添加如下内容：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;========================================================&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;[sumu]mount sumu&#39;s nfs dir (/mnt/nfs_app)......&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mount</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nfs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nolock,nfsvers=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 192.168.10.108:/home/sumu/4nfs/app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mnt/nfs_app</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;========================================================&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><img src="`+p+'" alt="image-20240831113614991" style="zoom:53%;"><p>可以看到开机的时候挂载完毕，已经可以正常使用了：</p><img src="'+h+`" alt="image-20240831113547106" style="zoom:50%;"><p>根据打印信息来看，这个文件应该是运行在最后的。</p><h2 id="四、usb-wifi" tabindex="-1">四、USB WiFi <a class="header-anchor" href="#四、usb-wifi" aria-label="Permalink to &quot;四、USB WiFi&quot;">​</a></h2><p>前面在体验出厂系统的时候还用到了 usb WiFi 模块，我们在学习应用开发的时候只需要在出厂系统上跑 app 程序就可以了，这样我们其实是可以使用这个模块，和电脑连接在同一个局域网下，这样就不需要插网线了。</p><h3 id="_1-启动并连接-wifi" tabindex="-1">1. 启动并连接 WiFi <a class="header-anchor" href="#_1-启动并连接-wifi" aria-label="Permalink to &quot;1. 启动并连接 WiFi&quot;">​</a></h3><p>这里就看《10-开发平台/05-IMX6ULL/LV020-基本功能测试.md》就可以了。连接完成后，可以 ping 一下电脑主机 WiFi 连接的 ip 和 ubuntu NAT 模式的 ip，会发现在同一个局域网下是可以 ping 通的。</p><h3 id="_2-挂载-ubuntu-共享目录" tabindex="-1">2. 挂载 ubuntu 共享目录 <a class="header-anchor" href="#_2-挂载-ubuntu-共享目录" aria-label="Permalink to &quot;2. 挂载 ubuntu 共享目录&quot;">​</a></h3><p>和上面的挂载命令是一样的：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mnt/nfs_app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mount</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nfs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nolock,nfsvers=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ubuntu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NAT模式下的I</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">P</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:/home/sumu/4nfs/app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mnt/nfs_app</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div>`,41)])])}const g=i(r,[["render",d]]);export{m as __pageData,g as default};
